use vstd::prelude::*;

verus! {
    // Given a non‐empty Vec<i32>, return its minimum element.
    // Postconditions:
    //   1) for all indices j < nums.len(): min <= nums[j]
    //   2) exists an index j < nums.len() such that min == nums[j]
    fn smallest_num(nums: &Vec<i32>) -> (min: i32)
        requires
            nums.len() > 0,
        ensures
            forall |j: usize| j < nums.len() ==> min <= nums[j],
        ensures
            exists |j: usize| j < nums.len() && min == nums[j],
    {
        let len = nums.len();
        // Initialize `small` to the first element.
        let mut small: i32 = nums[0];
        // We'll scan from i = 1 up to len.
        let mut i: usize = 1;
        while i < len
            // always 0 <= i <= len
            invariant
                i <= len,
            // `small` ≤ every element in nums[0..i]
            invariant
                forall |j: usize| j < i ==> small <= nums[j],
            // and `small` actually occurs in nums[0..i]
            invariant
                exists |j: usize| j < i && small == nums[j],
            // measure of progress
            decreases
                len - i,
        {
            let v = nums[i];
            if v < small {
                small = v;
            }
            i += 1;
        }
        // At i == len, the invariants give exactly the desired postconditions
        small
    }
}

fn main() {
    // optional: simple smoke test
    let v = vec![5, 3, 7, 2, 4];
    assert!(smallest_num(&v) == 2);
}